// Migration for IndexedDB using idb
import { openDB } from 'idb';

export async function migrate() {
  const db = await openDB('pacman-db', 1, {
    upgrade(db) {
      // high_scores store
      if (!db.objectStoreNames.contains('high_scores')) {
        const hsStore = db.createObjectStore('high_scores', { keyPath: 'id' });
        hsStore.createIndex('score_desc', 'score', { unique: false, multiEntry: false, locale: undefined, direction: 'prev' }); // descending
        hsStore.createIndex('by_initials', 'initials', { unique: false });
        hsStore.createIndex('by_created_at', 'created_at', { unique: false });
      }
      // preferences store – one record per user
      if (!db.objectStoreNames.contains('preferences')) {
        const prefStore = db.createObjectStore('preferences', { keyPath: 'user_id' });
        prefStore.createIndex('by_user_id', 'user_id', { unique: true });
      }
    },
    blocking() {
      console.warn('A newer version of the database is waiting to open.');
    },
    terminated() {
      console.error('Database connection was unexpectedly terminated.');
    }
  });
  return db;
}

// Seed a default preferences record if none exists
import { openDB } from 'idb';

export async function seedPreferences() {
  const db = await openDB('pacman-db', 1);
  const tx = db.transaction('preferences', 'readwrite');
  const store = tx.objectStore('preferences');
  const existing = await store.get('default_user');
  if (!existing) {
    await store.add({
      user_id: 'default_user',
      mute: false,
      color_blind_mode: false,
      last_played_level: 1,
      created_at: new Date(),
      updated_at: new Date()
    });
  }
  await tx.done;
}
